{
  "title": "add-log-level-env-var",
  "request": "Can we configure the Langfuse logger level via an environment variable? I'd like LANGFUSE_LOG_LEVEL to accept standard level names like INFO or DEBUG and have the logger respect that.",
  "edits": [
    {
      "path": "langfuse/logger.py",
      "search": "import logging",
      "replace": "import logging
import os"
    },
    {
      "path": "langfuse/logger.py",
      "search": "httpx_logger.setLevel(logging.WARNING)",
      "replace": "httpx_logger.setLevel(logging.WARNING)

# Override logger level from LANGFUSE_LOG_LEVEL env var if present
log_level_str = os.getenv("LANGFUSE_LOG_LEVEL")
if log_level_str:
    try:
        level = getattr(logging, log_level_str.upper())
        if isinstance(level, int):
            langfuse_logger.setLevel(level)
    except Exception:
        pass"
    }
  ],
  "test_path": "tests/unit/test_logger_env.py",
  "test": "import os
import importlib
import logging

# Set environment variable before importing the logger module
os.environ["LANGFUSE_LOG_LEVEL"] = "INFO"

# Reload the logger module to pick up the env var
import langfuse.logger as logger
importlib.reload(logger)

def test_logger_respects_env_level():
    assert logger.langfuse_logger.level == logging.INFO
    # Clean up: reset level and remove env var
    logger.langfuse_logger.setLevel(logging.WARNING)
    os.environ.pop("LANGFUSE_LOG_LEVEL")"
}
